import type {ServiceInventory} from './service-inventory';
import type {Booking} from '@/lib/pilot';
import type {PendingForward,ForwardEntry,CorrectionTotals} from '@/lib/service-forward';
export const serviceComponents=[['accommodation_minor','Accommodation'],['taxes_minor','Taxes'],['hotel_fees_minor','Property fees'],['ota_fees_minor','OTA fees'],['other_revenue_minor','Other revenue']] as const;
export type ServiceComponent=typeof serviceComponents[number][0];
export type AllocationInput={date:string}&Record<ServiceComponent,number>;
export type AllocationLine=AllocationInput&{total_minor:number;service_usage?:'overnight'|'same_day_use'|'unoccupied';tax_allocation:string;taxes:{code:string;amount_minor:number}[];fees:{code:string;amount_minor:number}[]};
export type ServiceTotals=Record<ServiceComponent,number>&{total_minor:number;revenue_minor:number;occupied_nights:number;complete?:boolean};
export type ServicePreview={inventory_snapshot?:ServiceInventory;api_version:2;corrections_hash:string;pending_adjustments:PendingForward[];ordinary_totals:ServiceTotals|null;correction_totals:CorrectionTotals;initialized:boolean;first_service_date?:string;next_service_date?:string;version?:number;time_zone?:string;civil_date?:string;can_close:boolean;preview_hash:string|null;generated_at:string;blockers:{code:string;reservation_id?:string}[];rows:{reservation_id:string;guest_name:string|null;source:string;status:string;occupied_night:boolean;allocation_source:string|null;blocker:string|null;allocation:AllocationLine|null}[];totals:ServiceTotals|null};
export type ServiceAllocation={reservation:Booking;pricing_hash:string;financial_basis:string;total_minor:number|null;component_totals:Record<ServiceComponent,number>;component_totals_fixed:boolean;allocation_source:string|null;lines:AllocationLine[];reason:string|null};
export type ServiceReceipt={replayed:boolean;service_date?:string;next_service_date:string;version:number;entry_count?:number;close_id?:string;totals?:ServiceTotals};
export type ServiceEntry=AllocationLine&{service_date:string;reservation_id:string;source_version:number;allocation_source:string;occupied_night:boolean;details:AllocationLine&{guest_name:string|null}};
export type ClosedServiceReport={api_version:2;forward_entries:ForwardEntry[];pending_adjustments:PendingForward[];ordinary_totals:ServiceTotals;correction_totals:CorrectionTotals;initialized:boolean;start:string;end:string;time_zone:string|null;first_service_date:string|null;next_service_date:string|null;generated_at:string;days:{service_date:string;close_id:string;closed_at:string;closed_by:string;entry_count:number;ordinary_entry_count:number;correction_entry_count:number;totals:ServiceTotals}[];entries:ServiceEntry[];totals:ServiceTotals;reconciliation_pending:{reservation_id:string;changed_at:string}[]};
export const blockerLabels:Record<string,string>={ledger_not_initialized:'Choose the first service day to begin.',property_time_zone_changed:'The property time zone differs from the ledger. Resolve it before closing.',service_day_not_finished:'This service day has not finished in the property time zone.',post_close_pricing_changed:'Charges changed after a day was closed. Reconcile the allocation.',arrival_not_resolved:'Resolve this arrival in Reservations.',overdue_stay_requires_extension:'Extend or check out this overdue stay in Reservations.',nightly_allocation_required:'Review and approve the nightly charge allocation.',pricing_changed:'Pricing changed. Review the nightly allocation.',folio_pricing_difference:'The folio and booking differ. Reconcile and allocate the charges.',folio_adjustment_allocation_required:'Allocate the folio adjustments to service nights.',charge_data_unavailable:'Complete and reconcile the reservation charges.',service_date_allocation_missing:'The service night is missing from the approved allocation.',unoccupied_night_requires_explicit_allocation:'Review this unoccupied night. Accommodation and property fees cannot be recognized as occupied revenue.'};
export function blockerLabel(code:string){return blockerLabels[code]??({stay_not_completed:'Complete or cancel the stay before reviewing a forward correction.',stay_not_fully_allocated_with_same_dates:'This stay is not fully allocated over its unchanged dates. Review nightly allocations for partial stays.',approved_correction_posting_missing:'An approved correction is missing its expected posting. Operator reconciliation is required.',tax_bucket_history_mismatch:'Tax category history requires operator reconciliation.',approved_correction_date_mismatch:'A pending correction has a different posting date. Resolve it before closing.',forward_adjustments_require_updated_client:'Use the updated close workflow to include forward corrections.'} as Record<string,string>)[code]??code.replaceAll('_',' ')}
export type ServiceCommand={rpc:'start_service_ledger'|'close_service_day'|'close_service_day_v2'|'approve_service_allocation'|'approve_service_forward';label:string;params:Record<string,unknown>&{p_request:string}};
export function validServiceCommand(value:unknown):value is ServiceCommand{
 if(!value||typeof value!=='object')return false;const v=value as ServiceCommand;
 if(!v.params||typeof v.params!=='object'||typeof v.label!=='string'||v.label.length>300||!/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(String(v.params.p_request)))return false;
 const p=v.params,keys=Object.keys(p).sort().join(','),date=(x:unknown)=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x),hash=(x:unknown)=>typeof x==='string'&&/^[a-f0-9]{64}$/.test(x),version=(x:unknown)=>Number.isSafeInteger(x)&&Number(x)>0,reason=(x:unknown)=>typeof x==='string'&&x.trim().length>=4&&x.length<=500;
 if(v.rpc==='start_service_ledger')return keys==='p_first_service_date,p_reason,p_request'&&date(p.p_first_service_date)&&reason(p.p_reason);
 if(v.rpc==='close_service_day')return keys==='p_expected_preview_hash,p_expected_version,p_request'&&hash(p.p_expected_preview_hash)&&version(p.p_expected_version);
 if(v.rpc==='close_service_day_v2')return keys==='p_expected_corrections_hash,p_expected_preview_hash,p_expected_version,p_request'&&hash(p.p_expected_corrections_hash)&&hash(p.p_expected_preview_hash)&&version(p.p_expected_version);
 if(v.rpc==='approve_service_forward'){
  const vector=(x:unknown,expected:string[])=>!!x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).sort().join(',')===expected.sort().join(',')&&Object.values(x).every(n=>Number.isSafeInteger(n)&&Math.abs(n)<=999999999999);
  return keys==='p_delta,p_expected_book_version,p_expected_preview_hash,p_expected_pricing_hash,p_expected_source_version,p_reason,p_request,p_reservation,p_tax_buckets'&&version(p.p_expected_book_version)&&version(p.p_expected_source_version)&&hash(p.p_expected_pricing_hash)&&hash(p.p_expected_preview_hash)&&/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(String(p.p_reservation))&&reason(p.p_reason)&&vector(p.p_delta,serviceComponents.map(([key])=>key))&&vector(p.p_tax_buckets,['legacy','city','state','lodging','unallocated']);
 }
 if(v.rpc!=='approve_service_allocation')return false;
 return keys==='p_expected_pricing_hash,p_expected_source_version,p_lines,p_reason,p_request,p_reservation'&&hash(p.p_expected_pricing_hash)&&version(p.p_expected_source_version)&&typeof p.p_reservation==='string'&&reason(p.p_reason)&&Array.isArray(p.p_lines)&&p.p_lines.length>=1&&p.p_lines.length<=30&&p.p_lines.every(line=>line&&typeof line==='object'&&Object.keys(line).sort().join(',')==='accommodation_minor,date,hotel_fees_minor,ota_fees_minor,other_revenue_minor,taxes_minor'&&date(line.date)&&serviceComponents.every(([key])=>Number.isSafeInteger(line[key])&&line[key]>=0&&line[key]<=999999999999));
}

export function serviceUsageLabel(occupiedNight:boolean,usage?:string):string {
 if(occupiedNight)return 'Overnight stay';
 if(usage==='same_day_use')return 'Same-day service (no overnight)';
 return 'No overnight occupancy';
}
